ee:variables.ee:set-variable:
%dw 2.0
import try from dw::Runtime
output application/java

fun toUtcDateTime(val) = 
    if (val == null or (val as String) == "") null
    else do {
        var rawStr = (val as String) replace " " with "T"
        var direct = try(() -> (rawStr as DateTime >> "UTC"))
        var withZ = if (direct.success) direct else try(() -> ((rawStr ++ "Z") as DateTime >> "UTC"))
        ---
        if (direct.success) direct.result
        else if (withZ.success) withZ.result
        else null
    }

var rankMap = {
    "LABEL_CREATED": 10,
    "PICKED_UP": 20,
    "IN_TRANSIT": 30,
    "ARRIVED_AT_HUB": 35,
    "OUT_FOR_DELIVERY": 40,
    "EXCEPTION": 42,
    "DELIVERY_ATTEMPTED": 45,
    "DELIVERED": 50,
    "RETURNED": 60
}
var currentRank = vars.targetShipment.status_rank default 10
var newRank = rankMap[vars.canonicalEvent.normalizedStatus] default 15

var lastTs = toUtcDateTime(vars.targetShipment.last_event_timestamp)
var incomingTs = toUtcDateTime(vars.canonicalEvent.eventTimestamp) default (now() >> "UTC")

// Out-of-order if incoming scan timestamp is strictly older than latest recorded event
var isOlder = if (lastTs != null) incomingTs < lastTs else false
// Or if already in a terminal state (DELIVERED or RETURNED) and receives an earlier transit scan
var isTerminal = (vars.targetShipment.current_status == "DELIVERED" or vars.targetShipment.current_status == "RETURNED")
var isDowngrade = isTerminal and (newRank < currentRank)

var outOfOrderCondition = isOlder or isDowngrade
---
{
    isOutOfOrder: outOfOrderCondition,
    currentRank: currentRank,
    newRank: newRank,
    processingResult: if (outOfOrderCondition) "OUT_OF_ORDER_RECORDED" else "PROCESSED"
}
